import re
from dataclasses import dataclass, field
from typing import Optional

HEADING = re.compile(r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$")
COMMENT_AT_EOL = re.compile(r"[ \t]*<!--.*?-->[ \t]*(?=\n|\Z)", re.DOTALL)
COMMENT = re.compile(r"[ \t]*<!--.*?-->", re.DOTALL)


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def strip_comments(text):
    return COMMENT.sub("", COMMENT_AT_EOL.sub("", text))


def clean_body(lines):
    out = []
    for line in lines:
        if not line.strip():
            if out and out[-1] == "":
                continue
            line = ""
        out.append(line)
    return "\n".join(out).strip("\n")


def parse_changelog(text):
    releases = []
    current = None
    for line in strip_comments(text).splitlines():
        if line.startswith("## "):
            match = HEADING.match(line)
            if match is None:
                current = None
                continue
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            body = clean_body(release.body)
            title = f"{release.version} ({release.date})" if release.date else release.version
            if not release.date:
                title = release.version
            return f"# {title}\n\n{body}\n"
    raise LookupError(version)
